'use strict';
// Python's file rules (src/languages/python/rules.js, P1): source, test and generated files,
// and the project a file belongs to.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { pythonRules, pythonProjectOf, GENERATED_HEAD_CHARS } = require('../src/languages/python/rules');
const { isTestPath } = require('../src/languages');

test('a .py or .pyi file is Python source; environments, caches and root build output are not', () => {
  for (const p of ['main.py', 'pkg/mod.pyi', 'src/pkg/tests/test_a.py', 'a\\b\\c.py', 'rebuild/x.py', 'distro/x.py', 'my_venv/x.py', 'pkg/build/x.py', 'src/pip/_internal/operations/build/wheel.py', 'pkg/dist/x.py']) assert.equal(pythonRules.handles(p), true, p);
  for (const p of ['main.ts', 'a.pyc', 'a.py.txt', 'README.md', 'venv/lib/x.py', '.venv/lib/x.py', 'a/site-packages/x/y.py', 'pkg/__pycache__/x.py', '.tox/py/x.py', 'build/lib/x.py', 'dist/x.pyi', 'a\\venv\\b.py', 'build\\lib\\x.py']) {
    assert.equal(pythonRules.handles(p), false, p);
  }
});

test('a test is test_*.py, *_test.py or conftest.py, wherever it is', () => {
  for (const p of ['test_a.py', 'pkg/test_a.py', 'pkg/a_test.py', 'conftest.py', 'pkg/conftest.py', 'pkg\\test_a.py']) assert.equal(pythonRules.isTest(p), true, p);
  for (const p of ['testing.py', 'test.py', 'contest.py', 'pkg/latest.py', 'pkg/a_tests.py', 'pkg/conftest.pyi.txt', 'pkg/mytest_a.py']) assert.equal(pythonRules.isTest(p), false, p);
});

test('a file under a shared test directory is a test whatever its name (shared rule)', () => {
  assert.equal(isTestPath('tests/helpers.py'), true);
  assert.equal(isTestPath('pkg/test/helpers.py'), true);
  assert.equal(isTestPath('pkg/helpers.py'), false);
});

test('generated by name: protocol buffer modules and stubs', () => {
  for (const p of ['api/service_pb2.py', 'api/service_pb2_grpc.py', 'api/service_pb2.pyi', 'a\\service_pb2.py']) {
    assert.equal(pythonRules.isGenerated(p, 'x = 1\n'), true, p);
  }
  for (const p of ['api/service.py', 'api/pb2.py', 'api/service_pb2_helpers.py']) assert.equal(pythonRules.isGenerated(p, 'x = 1\n'), false, p);
});

test('generated by a header comment, only before the first line of code', () => {
  assert.equal(pythonRules.isGenerated('a.py', '# Generated by the protocol buffer compiler.  DO NOT EDIT!\nimport x\n'), true);
  assert.equal(pythonRules.isGenerated('a.py', '#!/usr/bin/env python\n# -*- coding: utf-8 -*-\n\n  # Generated by tool\nimport x\n'), true, 'after a shebang, encoding line and blank line');
  assert.equal(pythonRules.isGenerated('a.py', '# @generated\nimport x\n'), true);
  assert.equal(pythonRules.isGenerated('a.py', '# This file is @generated by tool\nimport x\n'), true);
  assert.equal(pythonRules.isGenerated('a.py', '# Generated by tool\r\nimport x\r\n'), true, 'CRLF line ends');
  assert.equal(pythonRules.isGenerated('a.py', 'import x\n# Generated by tool\n'), false, 'after code');
  assert.equal(pythonRules.isGenerated('a.py', '"""Docstring."""\n# Generated by tool\n'), false, 'after a docstring');
  assert.equal(pythonRules.isGenerated('a.py', '# generated by tool\nimport x\n'), false, 'case-sensitive');
  assert.equal(pythonRules.isGenerated('a.py', '# Not Generated by tool\nimport x\n'), false, 'not at the start of the comment');
  assert.equal(pythonRules.isGenerated('a.py', 'x = "# Generated by"\n'), false, 'not a comment');
  assert.equal(pythonRules.isGenerated('a.py', ''), false, 'an empty file');
});

test('the generated comment is looked for only in the head of the file', () => {
  const late = `${'# filler\n'.repeat(Math.ceil(GENERATED_HEAD_CHARS / 9))}# Generated by x\nimport x\n`;
  assert.equal(pythonRules.isGenerated('a.py', late), false, 'past the head: analysed, as documented');
});

test('pythonProjectOf: the nearest pyproject.toml, setup.py or setup.cfg', () => {
  const repo = fs.mkdtempSync(path.join(os.tmpdir(), 'it-python-rules-'));
  try {
    fs.mkdirSync(path.join(repo, 'libs', 'inner', 'pkg'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'libs', 'plain'), { recursive: true });
    fs.mkdirSync(path.join(repo, 'apps', 'py'), { recursive: true });
    fs.writeFileSync(path.join(repo, 'pyproject.toml'), '');
    fs.writeFileSync(path.join(repo, 'libs', 'inner', 'setup.cfg'), '');
    fs.writeFileSync(path.join(repo, 'apps', 'py', 'setup.py'), '');
    assert.deepEqual(pythonProjectOf('top.py', repo), { component: '(root)', projectRoot: '' });
    assert.deepEqual(pythonProjectOf('libs/plain/x.py', repo), { component: '(root)', projectRoot: '' }, 'falls back to the root project');
    assert.deepEqual(pythonProjectOf('libs/inner/pkg/x.py', repo), { component: 'libs/inner', projectRoot: 'libs/inner' }, 'nested, setup.cfg');
    assert.deepEqual(pythonProjectOf('apps/py/x.py', repo), { component: 'apps/py', projectRoot: 'apps/py' }, 'setup.py');
    fs.rmSync(path.join(repo, 'pyproject.toml'));
    assert.deepEqual(pythonProjectOf('libs/plain/x.py', repo), { component: '(no pyproject.toml)', projectRoot: '' });
    assert.deepEqual(pythonProjectOf('top.py', repo), { component: '(no pyproject.toml)', projectRoot: '' });
  } finally {
    fs.rmSync(repo, { recursive: true, force: true });
  }
});
